/*
=================
S_AL_Format
=================
*/

unsafe extern "C" fn S_AL_Format(mut width: i32, mut channels: i32) -> ALuint {
    let mut format: ALuint = 0x1101 as i32 as ALuint;
    // Work out format
    if width == 1 as i32 {
        if channels == 1 as i32 {
            format = 0x1100 as i32 as ALuint
        } else if channels == 2 as i32 {
            format = 0x1102 as i32 as ALuint
        }
    } else if width == 2 as i32 {
        if channels == 1 as i32 {
            format = 0x1101 as i32 as ALuint
        } else if channels == 2 as i32 {
            format = 0x1103 as i32 as ALuint
        }
    }
    return format;
}
/*
=================
S_AL_ErrorMsg
=================
*/

unsafe extern "C" fn S_AL_ErrorMsg(mut error: ALenum) -> *const libc::c_char {
    match error {
        0 => return b"No error\x00" as *const u8 as *const libc::c_char,
        40961 => return b"Invalid name\x00" as *const u8 as *const libc::c_char,
        40962 => return b"Invalid enumerator\x00" as *const u8 as *const libc::c_char,
        40963 => return b"Invalid value\x00" as *const u8 as *const libc::c_char,
        40964 => return b"Invalid operation\x00" as *const u8 as *const libc::c_char,
        40965 => return b"Out of memory\x00" as *const u8 as *const libc::c_char,
        _ => return b"Unknown error\x00" as *const u8 as *const libc::c_char,
    };
}
/*
=================
S_AL_ClearError
=================
*/

unsafe extern "C" fn S_AL_ClearError(mut quiet: qboolean) {
    let mut error: i32 = crate::src::client::qal::qalGetError.expect("non-null function pointer")();
    if quiet as u64 != 0 {
        return;
    }
    if error != 0 as i32 {
        Com_Printf(
            b"^3WARNING: unhandled AL error: %s\n\x00" as *const u8 as *const libc::c_char,
            S_AL_ErrorMsg(error),
        );
    };
}

static mut alBuffersInitialised: qboolean = qfalse;

static mut knownSfx: [alSfx_t; 4096] = [alSfx_t {
    filename: [0; 64],
    buffer: 0,
    info: snd_info_t {
        rate: 0,
        width: 0,
        channels: 0,
        samples: 0,
        size: 0,
        dataofs: 0,
    },
    isDefault: qfalse,
    isDefaultChecked: qfalse,
    inMemory: qfalse,
    isLocked: qfalse,
    lastUsedTime: 0,
    loopCnt: 0,
    loopActiveCnt: 0,
    masterLoopSrc: 0,
}; 4096];

static mut numSfx: sfxHandle_t = 0 as i32;

static mut default_sfx: sfxHandle_t = 0;
/*
=================
S_AL_BufferFindFree

Find a free handle
=================
*/

unsafe extern "C" fn S_AL_BufferFindFree() -> sfxHandle_t {
    let mut i: i32 = 0;
    i = 0 as i32;
    while i < 4096 as i32 {
        // Got one
        if knownSfx[i as usize].filename[0 as i32 as usize] as i32 == '\u{0}' as i32 {
            if i >= numSfx {
                numSfx = i + 1 as i32
            }
            return i;
        }
        i += 1
    }
    // Shit...
    Com_Error(
        ERR_FATAL as i32,
        b"S_AL_BufferFindFree: No free sound handles\x00" as *const u8 as *const libc::c_char,
    );
}
/*
=================
S_AL_BufferFind

Find a sound effect if loaded, set up a handle otherwise
=================
*/

unsafe extern "C" fn S_AL_BufferFind(mut filename: *const libc::c_char) -> sfxHandle_t {
    // Look it up in the table
    let mut sfx: sfxHandle_t = -(1 as i32);
    let mut i: i32 = 0;
    if filename.is_null() {
        Com_Error(
            ERR_FATAL as i32,
            b"Sound name is NULL\x00" as *const u8 as *const libc::c_char,
        );
    }
    if *filename.offset(0 as i32 as isize) == 0 {
        Com_Printf(b"^3WARNING: Sound name is empty\n\x00" as *const u8 as *const libc::c_char);
        return 0 as i32;
    }
    if crate::stdlib::strlen(filename) >= 64 as i32 as usize {
        Com_Printf(
            b"^3WARNING: Sound name is too long: %s\n\x00" as *const u8 as *const libc::c_char,
            filename,
        );
        return 0 as i32;
    }
    if *filename.offset(0 as i32 as isize) as i32 == '*' as i32 {
        Com_Printf(
            b"^3WARNING: Tried to load player sound directly: %s\n\x00" as *const u8
                as *const libc::c_char,
            filename,
        );
        return 0 as i32;
    }
    i = 0 as i32;
    while i < numSfx {
        if Q_stricmp(knownSfx[i as usize].filename.as_mut_ptr(), filename) == 0 {
            sfx = i;
            break;
        } else {
            i += 1
        }
    }
    // Not found in table?
    if sfx == -(1 as i32) {
        let mut ptr: *mut alSfx_t = 0 as *mut alSfx_t;
        sfx = S_AL_BufferFindFree();
        // Clear and copy the filename over
        ptr = &mut *knownSfx.as_mut_ptr().offset(sfx as isize) as *mut alSfx_t;
        crate::stdlib::memset(
            ptr as *mut libc::c_void,
            0 as i32,
            ::std::mem::size_of::<alSfx_t>() as usize,
        );
        (*ptr).masterLoopSrc = -(1 as i32);
        libc::strcpy((*ptr).filename.as_mut_ptr(), filename);
    }
    // Return the handle
    return sfx;
}
/*
=================
S_AL_BufferUseDefault
=================
*/

unsafe extern "C" fn S_AL_BufferUseDefault(mut sfx: sfxHandle_t) {
    if sfx == default_sfx {
        Com_Error(
            ERR_FATAL as i32,
            b"Can\'t load default sound effect %s\x00" as *const u8 as *const libc::c_char,
            knownSfx[sfx as usize].filename.as_mut_ptr(),
        );
    }
    Com_Printf(
        b"^3WARNING: Using default sound for %s\n\x00" as *const u8 as *const libc::c_char,
        knownSfx[sfx as usize].filename.as_mut_ptr(),
    );
    knownSfx[sfx as usize].isDefault = qtrue;
    knownSfx[sfx as usize].buffer = knownSfx[default_sfx as usize].buffer;
}
/*
=================
S_AL_BufferUnload
=================
*/

unsafe extern "C" fn S_AL_BufferUnload(mut sfx: sfxHandle_t) {
    if knownSfx[sfx as usize].filename[0 as i32 as usize] as i32 == '\u{0}' as i32 {
        return;
    }
    if knownSfx[sfx as usize].inMemory as u64 == 0 {
        return;
    }
    // Delete it
    S_AL_ClearError(qfalse);
    crate::src::client::qal::qalDeleteBuffers.expect("non-null function pointer")(
        1 as i32,
        &mut (*knownSfx.as_mut_ptr().offset(sfx as isize)).buffer,
    );
    if crate::src::client::qal::qalGetError.expect("non-null function pointer")() != 0 as i32 {
        Com_Printf(
            b"^1ERROR: Can\'t delete sound buffer for %s\n\x00" as *const u8 as *const libc::c_char,
            knownSfx[sfx as usize].filename.as_mut_ptr(),
        );
    }
    knownSfx[sfx as usize].inMemory = qfalse;
}
/*
=================
S_AL_BufferEvict
=================
*/

unsafe extern "C" fn S_AL_BufferEvict() -> qboolean {
    let mut i: i32 = 0;
    let mut oldestBuffer: i32 = -(1 as i32);
    let mut oldestTime: i32 = crate::src::sys::sys_unix::Sys_Milliseconds();
    i = 0 as i32;
    while i < numSfx {
        if !(knownSfx[i as usize].filename[0 as i32 as usize] == 0) {
            if !(knownSfx[i as usize].inMemory as u64 == 0) {
                if knownSfx[i as usize].lastUsedTime < oldestTime {
                    oldestTime = knownSfx[i as usize].lastUsedTime;
                    oldestBuffer = i
                }
            }
        }
        i += 1
    }
    if oldestBuffer >= 0 as i32 {
        S_AL_BufferUnload(oldestBuffer);
        return qtrue;
    } else {
        return qfalse;
    };
}
/*
=================
S_AL_GenBuffers
=================
*/

unsafe extern "C" fn S_AL_GenBuffers(
    mut numBuffers: ALsizei,
    mut buffers: *mut ALuint,
    mut name: *const libc::c_char,
) -> qboolean {
    let mut error: ALenum = 0;
    S_AL_ClearError(qfalse);
    crate::src::client::qal::qalGenBuffers.expect("non-null function pointer")(numBuffers, buffers);
    error = crate::src::client::qal::qalGetError.expect("non-null function pointer")();
    // If we ran out of buffers, start evicting the least recently used sounds
    while error == 0xa003 as i32 {
        if S_AL_BufferEvict() as u64 == 0 {
            Com_Printf(b"^1ERROR: Out of audio buffers\n\x00" as *const u8 as *const libc::c_char);
            return qfalse;
        }
        // Try again
        S_AL_ClearError(qfalse);
        crate::src::client::qal::qalGenBuffers.expect("non-null function pointer")(
            numBuffers, buffers,
        );
        error = crate::src::client::qal::qalGetError.expect("non-null function pointer")()
    }
    if error != 0 as i32 {
        Com_Printf(
            b"^1ERROR: Can\'t create a sound buffer for %s - %s\n\x00" as *const u8
                as *const libc::c_char,
            name,
            S_AL_ErrorMsg(error),
        );
        return qfalse;
    }
    return qtrue;
}
/*
=================
S_AL_BufferLoad
=================
*/

unsafe extern "C" fn S_AL_BufferLoad(mut sfx: sfxHandle_t, mut cache: qboolean) {
    let mut error: ALenum = 0;
    let mut format: ALuint = 0;
    let mut data: *mut libc::c_void = 0 as *mut libc::c_void;
    let mut info: snd_info_t = snd_info_t {
        rate: 0,
        width: 0,
        channels: 0,
        samples: 0,
        size: 0,
        dataofs: 0,
    };
    let mut curSfx: *mut alSfx_t = &mut *knownSfx.as_mut_ptr().offset(sfx as isize) as *mut alSfx_t;
    // Nothing?
    if (*curSfx).filename[0 as i32 as usize] as i32 == '\u{0}' as i32 {
        return;
    }
    // Already done?
    if (*curSfx).inMemory as u32 != 0
        || (*curSfx).isDefault as u32 != 0
        || cache as u64 == 0 && (*curSfx).isDefaultChecked as u32 != 0
    {
        return;
    }
    // Try to load
    data = S_CodecLoad(
        (*curSfx).filename.as_mut_ptr(),
        &mut info as *mut _ as *mut snd_info_s,
    );
    if data.is_null() {
        S_AL_BufferUseDefault(sfx);
        return;
    }
    (*curSfx).isDefaultChecked = qtrue;
    if cache as u64 == 0 {
        // Don't create AL cache
        crate::src::qcommon::common::Hunk_FreeTempMemory(data);
        return;
    }
    format = S_AL_Format(info.width, info.channels);
    // Create a buffer
    if S_AL_GenBuffers(
        1 as i32,
        &mut (*curSfx).buffer,
        (*curSfx).filename.as_mut_ptr(),
    ) as u64
        == 0
    {
        S_AL_BufferUseDefault(sfx);
        crate::src::qcommon::common::Hunk_FreeTempMemory(data);
        return;
    }
    // Fill the buffer
    if info.size == 0 as i32 {
        // We have no data to buffer, so buffer silence
        let mut dummyData: [byte; 2] = [0 as i32 as byte, 0];
        crate::src::client::qal::qalBufferData.expect("non-null function pointer")(
            (*curSfx).buffer,
            0x1101 as i32,
            dummyData.as_mut_ptr() as *mut libc::c_void,
            2 as i32,
            22050 as i32,
        );
    } else {
        crate::src::client::qal::qalBufferData.expect("non-null function pointer")(
            (*curSfx).buffer,
            format as ALenum,
            data,
            info.size,
            info.rate,
        );
    }
    error = crate::src::client::qal::qalGetError.expect("non-null function pointer")();
    // If we ran out of memory, start evicting the least recently used sounds
    while error == 0xa005 as i32 {
        if S_AL_BufferEvict() as u64 == 0 {
            crate::src::client::qal::qalDeleteBuffers.expect("non-null function pointer")(
                1 as i32,
                &mut (*curSfx).buffer,
            );
            S_AL_BufferUseDefault(sfx);
            crate::src::qcommon::common::Hunk_FreeTempMemory(data);
            Com_Printf(
                b"^1ERROR: Out of memory loading %s\n\x00" as *const u8 as *const libc::c_char,
                (*curSfx).filename.as_mut_ptr(),
            );
            return;
        }
        // Try load it again
        crate::src::client::qal::qalBufferData.expect("non-null function pointer")(
            (*curSfx).buffer,
            format as ALenum,
            data,
            info.size,
            info.rate,
        );
        error = crate::src::client::qal::qalGetError.expect("non-null function pointer")()
    }
    // Some other error condition
    if error != 0 as i32 {
        crate::src::client::qal::qalDeleteBuffers.expect("non-null function pointer")(
            1 as i32,
            &mut (*curSfx).buffer,
        );
        S_AL_BufferUseDefault(sfx);
        crate::src::qcommon::common::Hunk_FreeTempMemory(data);
        Com_Printf(
            b"^1ERROR: Can\'t fill sound buffer for %s - %s\n\x00" as *const u8
                as *const libc::c_char,
            (*curSfx).filename.as_mut_ptr(),
            S_AL_ErrorMsg(error),
        );
        return;
    }
    (*curSfx).info = info;
    // Free the memory
    crate::src::qcommon::common::Hunk_FreeTempMemory(data);
    // Woo!
    (*curSfx).inMemory = qtrue;
}
/*
=================
S_AL_BufferUse
=================
*/

unsafe extern "C" fn S_AL_BufferUse(mut sfx: sfxHandle_t) {
    if knownSfx[sfx as usize].filename[0 as i32 as usize] as i32 == '\u{0}' as i32 {
        return;
    }
    if knownSfx[sfx as usize].inMemory as u64 == 0 && knownSfx[sfx as usize].isDefault as u64 == 0 {
        S_AL_BufferLoad(sfx, qtrue);
    }
    knownSfx[sfx as usize].lastUsedTime = crate::src::sys::sys_unix::Sys_Milliseconds();
}
/*
=================
S_AL_BufferInit
=================
*/

unsafe extern "C" fn S_AL_BufferInit() -> qboolean {
    if alBuffersInitialised as u64 != 0 {
        return qtrue;
    }
    // Clear the hash table, and SFX table
    crate::stdlib::memset(
        knownSfx.as_mut_ptr() as *mut libc::c_void,
        0 as i32,
        ::std::mem::size_of::<[alSfx_t; 4096]>() as usize,
    );
    numSfx = 0 as i32;
    // Load the default sound, and lock it
    default_sfx =
        S_AL_BufferFind(b"sound/feedback/hit.wav\x00" as *const u8 as *const libc::c_char);
    S_AL_BufferUse(default_sfx);
    knownSfx[default_sfx as usize].isLocked = qtrue;
    // All done
    alBuffersInitialised = qtrue;
    return qtrue;
}
/*
=================
S_AL_BufferShutdown
=================
*/

unsafe extern "C" fn S_AL_BufferShutdown() {
    let mut i: i32 = 0;
    if alBuffersInitialised as u64 == 0 {
        return;
    }
    // Unlock the default sound effect
    knownSfx[default_sfx as usize].isLocked = qfalse;
    // Free all used effects
    i = 0 as i32;
    while i < numSfx {
        S_AL_BufferUnload(i);
        i += 1
    }
    // Clear the tables
    numSfx = 0 as i32;
    // All undone
    alBuffersInitialised = qfalse;
}
/*
=================
S_AL_RegisterSound
=================
*/

unsafe extern "C" fn S_AL_RegisterSound(
    mut sample: *const libc::c_char,
    mut _compressed: qboolean,
) -> sfxHandle_t {
    let mut sfx: sfxHandle_t = S_AL_BufferFind(sample);
    if knownSfx[sfx as usize].inMemory as u64 == 0 && knownSfx[sfx as usize].isDefault as u64 == 0 {
        S_AL_BufferLoad(sfx, (*s_alPrecache).integer as qboolean);
    }
    knownSfx[sfx as usize].lastUsedTime = crate::src::qcommon::common::Com_Milliseconds();
    if knownSfx[sfx as usize].isDefault as u64 != 0 {
        return 0 as i32;
    }
    return sfx;
}
/*
=================
S_AL_BufferGet

Return's a sfx's buffer
=================
*/

unsafe extern "C" fn S_AL_BufferGet(mut sfx: sfxHandle_t) -> ALuint {
    return knownSfx[sfx as usize].buffer;
}

static mut srcList: [src_t; 128] = [src_t {
    alSource: 0,
    sfx: 0,
    lastUsedTime: 0,
    priority: SRCPRI_AMBIENT,
    entity: 0,
    channel: 0,
    isActive: qfalse,
    isPlaying: qfalse,
    isLocked: qfalse,
    isLooping: qfalse,
    isTracking: qfalse,
    isStream: qfalse,
    curGain: 0.,
    scaleGain: 0.,
    lastTimePos: 0.,
    lastSampleTime: 0,
    loopSpeakerPos: [0.; 3],
    local: qfalse,
}; 128];

static mut srcCount: i32 = 0 as i32;

static mut srcActiveCnt: i32 = 0 as i32;

static mut alSourcesInitialised: qboolean = qfalse;

static mut lastListenerNumber: i32 = -(1 as i32);

static mut lastListenerOrigin: vec3_t = [0.0f32, 0.0f32, 0.0f32];

static mut entityList: [sentity_t; 1024] = [sentity_t {
    origin: [0.; 3],
    srcAllocated: qfalse,
    srcIndex: 0,
    loopAddedThisFrame: qfalse,
    loopPriority: SRCPRI_AMBIENT,
    loopSfx: 0,
    startLoopingSound: qfalse,
}; 1024];
/*
=================
S_AL_SanitiseVector
=================
*/

unsafe extern "C" fn _S_AL_SanitiseVector(mut v: *mut vec_t, mut line: i32) {
    if Q_isnan(*v.offset(0 as i32 as isize)) != 0
        || Q_isnan(*v.offset(1 as i32 as isize)) != 0
        || Q_isnan(*v.offset(2 as i32 as isize)) != 0
    {
        crate::src::qcommon::common::Com_DPrintf(b"^3WARNING: vector with one or more NaN components being passed to OpenAL at %s:%d -- zeroing\n\x00"
                        as *const u8 as *const libc::c_char,
                    b"code/client/snd_openal.c\x00" as *const u8 as
                        *const libc::c_char, line);
        let ref mut fresh0 = *v.offset(2 as i32 as isize);
        *fresh0 = 0 as i32 as vec_t;
        let ref mut fresh1 = *v.offset(1 as i32 as isize);
        *fresh1 = *fresh0;
        *v.offset(0 as i32 as isize) = *fresh1
    };
}
/*
=================
S_AL_Gain
Set gain to 0 if muted, otherwise set it to given value.
=================
*/

unsafe extern "C" fn S_AL_Gain(mut source: ALuint, mut gainval: f32) {
    if (*s_muted).integer != 0 {
        crate::src::client::qal::qalSourcef.expect("non-null function pointer")(
            source,
            0x100a as i32,
            0.0f32,
        );
    } else {
        crate::src::client::qal::qalSourcef.expect("non-null function pointer")(
            source,
            0x100a as i32,
            gainval,
        );
    };
}
/*
=================
S_AL_ScaleGain
Adapt the gain if necessary to get a quicker fadeout when the source is too far away.
=================
*/

unsafe extern "C" fn S_AL_ScaleGain(mut chksrc: *mut src_t, mut origin: *mut vec_t) {
    let mut distance: f32 = 0.;
    if (*chksrc).local as u64 == 0 {
        distance = Distance(
            origin as *const vec_t,
            lastListenerOrigin.as_mut_ptr() as *const vec_t,
        )
    }
    // If we exceed a certain distance, scale the gain linearly until the sound
    // vanishes into nothingness.
    if (*chksrc).local as u64 == 0 && {
        distance -= (*s_alMaxDistance).value;
        (distance) > 0 as i32 as f32
    } {
        let mut scaleFactor: f32 = 0.;
        if distance >= (*s_alGraceDistance).value {
            scaleFactor = 0.0f32
        } else {
            scaleFactor = 1.0f32 - distance / (*s_alGraceDistance).value
        }
        scaleFactor *= (*chksrc).curGain;
        if (*chksrc).scaleGain != scaleFactor {
            (*chksrc).scaleGain = scaleFactor;
            S_AL_Gain((*chksrc).alSource, (*chksrc).scaleGain);
        }
    } else if (*chksrc).scaleGain != (*chksrc).curGain {
        (*chksrc).scaleGain = (*chksrc).curGain;
        S_AL_Gain((*chksrc).alSource, (*chksrc).scaleGain);
    };
}
/*
=================
S_AL_HearingThroughEntity

Also see S_Base_HearingThroughEntity
=================
*/

unsafe extern "C" fn S_AL_HearingThroughEntity(mut entityNum: i32) -> qboolean {
    let mut distanceSq: f32 = 0.;
    if lastListenerNumber == entityNum {
        // This is an outrageous hack to detect
        // whether or not the player is rendering in third person or not. We can't
        // ask the renderer because the renderer has no notion of entities and we
        // can't ask cgame since that would involve changing the API and hence mod
        // compatibility. I don't think there is any way around this, but I'll leave
        // the FIXME just in case anyone has a bright idea.
        distanceSq = DistanceSquared(
            entityList[entityNum as usize].origin.as_mut_ptr() as *const vec_t,
            lastListenerOrigin.as_mut_ptr() as *const vec_t,
        );
        if distanceSq > 48.0f32 * 48.0f32 {
            //we're the player
            return qfalse;
        } else {
            return qtrue;
        }
    } else {
        return qfalse;
    }; //we're the player, but third person
       //not the player
}
/*
=================
S_AL_SrcInit
=================
*/

unsafe extern "C" fn S_AL_SrcInit() -> qboolean {
    let mut i: i32 = 0;
    let mut limit: i32 = 0;
    // Clear the sources data structure
    crate::stdlib::memset(
        srcList.as_mut_ptr() as *mut libc::c_void,
        0 as i32,
        ::std::mem::size_of::<[src_t; 128]>() as usize,
    );
    srcCount = 0 as i32;
    srcActiveCnt = 0 as i32;
    // Cap s_alSources to MAX_SRC
    limit = (*s_alSources).integer;
    if limit > 128 as i32 {
        limit = 128 as i32
    } else if limit < 16 as i32 {
        limit = 16 as i32
    }
    S_AL_ClearError(qfalse);
    // Allocate as many sources as possible
    i = 0 as i32;
    while i < limit {
        crate::src::client::qal::qalGenSources.expect("non-null function pointer")(
            1 as i32,
            &mut (*srcList.as_mut_ptr().offset(i as isize)).alSource,
        );
        if crate::src::client::qal::qalGetError.expect("non-null function pointer")() != 0 as i32 {
            break;
        }
        srcCount += 1;
        i += 1
    }
    // All done. Print this for informational purposes
    Com_Printf(
        b"Allocated %d sources.\n\x00" as *const u8 as *const libc::c_char,
        srcCount,
    );
    alSourcesInitialised = qtrue;
    return qtrue;
}
/*
=================
S_AL_SrcShutdown
=================
*/

unsafe extern "C" fn S_AL_SrcShutdown() {
    let mut i: i32 = 0;
    let mut curSource: *mut src_t = 0 as *mut src_t;
    if alSourcesInitialised as u64 == 0 {
        return;
    }
    // Destroy all the sources
    i = 0 as i32;
    while i < srcCount {
        curSource = &mut *srcList.as_mut_ptr().offset(i as isize) as *mut src_t;
        if (*curSource).isLocked as u64 != 0 {
            crate::src::qcommon::common::Com_DPrintf(
                b"^3WARNING: Source %d is locked\n\x00" as *const u8 as *const libc::c_char,
                i,
            );
        }
        if (*curSource).entity > 0 as i32 {
            entityList[(*curSource).entity as usize].srcAllocated = qfalse
        }
        crate::src::client::qal::qalSourceStop.expect("non-null function pointer")(
            srcList[i as usize].alSource,
        );
        crate::src::client::qal::qalDeleteSources.expect("non-null function pointer")(
            1 as i32,
            &mut (*srcList.as_mut_ptr().offset(i as isize)).alSource,
        );
        i += 1
    }
    crate::stdlib::memset(
        srcList.as_mut_ptr() as *mut libc::c_void,
        0 as i32,
        ::std::mem::size_of::<[src_t; 128]>() as usize,
    );
    alSourcesInitialised = qfalse;
}
/*
=================
S_AL_SrcSetup
=================
*/

unsafe extern "C" fn S_AL_SrcSetup(
    mut src: srcHandle_t,
    mut sfx: sfxHandle_t,
    mut priority: alSrcPriority_t,
    mut entity: i32,
    mut channel: i32,
    mut local: qboolean,
) {
    let mut curSource: *mut src_t = 0 as *mut src_t;
    // Set up src struct
    curSource = &mut *srcList.as_mut_ptr().offset(src as isize) as *mut src_t;
    (*curSource).lastUsedTime = crate::src::sys::sys_unix::Sys_Milliseconds();
    (*curSource).sfx = sfx;
    (*curSource).priority = priority;
    (*curSource).entity = entity;
    (*curSource).channel = channel;
    (*curSource).isPlaying = qfalse;
    (*curSource).isLocked = qfalse;
    (*curSource).isLooping = qfalse;
    (*curSource).isTracking = qfalse;
    (*curSource).isStream = qfalse;
    (*curSource).curGain = (*s_alGain).value * (*s_volume).value;
    (*curSource).scaleGain = (*curSource).curGain;
    (*curSource).local = local;
    // Set up OpenAL source
    if sfx >= 0 as i32 {
        // Mark the SFX as used, and grab the raw AL buffer
        S_AL_BufferUse(sfx);
        crate::src::client::qal::qalSourcei.expect("non-null function pointer")(
            (*curSource).alSource,
            0x1009 as i32,
            S_AL_BufferGet(sfx) as ALint,
        );
    }
    crate::src::client::qal::qalSourcef.expect("non-null function pointer")(
        (*curSource).alSource,
        0x1003 as i32,
        1.0f32,
    );
    S_AL_Gain((*curSource).alSource, (*curSource).curGain);
    crate::src::client::qal::qalSourcefv.expect("non-null function pointer")(
        (*curSource).alSource,
        0x1004 as i32,
        vec3_origin.as_mut_ptr(),
    );
    crate::src::client::qal::qalSourcefv.expect("non-null function pointer")(
        (*curSource).alSource,
        0x1006 as i32,
        vec3_origin.as_mut_ptr(),
    );
    crate::src::client::qal::qalSourcei.expect("non-null function pointer")(
        (*curSource).alSource,
        0x1007 as i32,
        0 as i32,
    );
    crate::src::client::qal::qalSourcef.expect("non-null function pointer")(
        (*curSource).alSource,
        0x1020 as i32,
        (*s_alMinDistance).value,
    );
    if local as u64 != 0 {
        crate::src::client::qal::qalSourcei.expect("non-null function pointer")(
            (*curSource).alSource,
            0x202 as i32,
            1 as i32,
        );
        crate::src::client::qal::qalSourcef.expect("non-null function pointer")(
            (*curSource).alSource,
            0x1021 as i32,
            0.0f32,
        );
    } else {
        crate::src::client::qal::qalSourcei.expect("non-null function pointer")(
            (*curSource).alSource,
            0x202 as i32,
            0 as i32,
        );
        crate::src::client::qal::qalSourcef.expect("non-null function pointer")(
            (*curSource).alSource,
            0x1021 as i32,
            (*s_alRolloff).value,
        );
    };
}
/*
=================
S_AL_SaveLoopPos
Remove given source as loop master if it is the master and hand off master status to another source in this case.
=================
*/

unsafe extern "C" fn S_AL_SaveLoopPos(mut dest: *mut src_t, mut alSource: ALuint) {
    let mut error: i32 = 0;
    S_AL_ClearError(qfalse);
    crate::src::client::qal::qalGetSourcef.expect("non-null function pointer")(
        alSource,
        0x1024 as i32,
        &mut (*dest).lastTimePos,
    );
    error = crate::src::client::qal::qalGetError.expect("non-null function pointer")();
    if error != 0 as i32 {
        // Old OpenAL implementations don't support AL_SEC_OFFSET
        if error != 0xa002 as i32 {
            Com_Printf(
                b"^3WARNING: Could not get time offset for alSource %d: %s\n\x00" as *const u8
                    as *const libc::c_char,
                alSource,
                S_AL_ErrorMsg(error),
            );
        }
        (*dest).lastTimePos = -(1 as i32) as f32
    } else {
        (*dest).lastSampleTime = crate::src::sys::sys_unix::Sys_Milliseconds()
    };
}
/*
=================
S_AL_NewLoopMaster
Remove given source as loop master if it is the master and hand off master status to another source in this case.
=================
*/

unsafe extern "C" fn S_AL_NewLoopMaster(mut rmSource: *mut src_t, mut iskilled: qboolean) {
    let mut index: i32 = 0;
    let mut curSource: *mut src_t = 0 as *mut src_t;
    let mut curSfx: *mut alSfx_t = 0 as *mut alSfx_t;
    curSfx = &mut *knownSfx.as_mut_ptr().offset((*rmSource).sfx as isize) as *mut alSfx_t;
    if (*rmSource).isPlaying as u64 != 0 {
        (*curSfx).loopActiveCnt -= 1
    }
    if iskilled as u64 != 0 {
        (*curSfx).loopCnt -= 1
    }
    if (*curSfx).loopCnt != 0 {
        if (*rmSource).priority as u32 == SRCPRI_ENTITY as i32 as u32 {
            if iskilled as u64 == 0 && (*rmSource).isPlaying as u32 != 0 {
                // only sync ambient loops...
                // It makes more sense to have sounds for weapons/projectiles unsynced
                S_AL_SaveLoopPos(rmSource, (*rmSource).alSource);
            }
        } else if (*curSfx).masterLoopSrc != -(1 as i32)
            && rmSource
                == &mut *srcList
                    .as_mut_ptr()
                    .offset((*curSfx).masterLoopSrc as isize) as *mut src_t
        {
            let mut firstInactive: i32 = -(1 as i32);
            // Only if rmSource was the master and if there are still playing loops for
            // this sound will we need to find a new master.
            if iskilled as u32 != 0 || (*curSfx).loopActiveCnt != 0 {
                index = 0 as i32;
                while index < srcCount {
                    curSource = &mut *srcList.as_mut_ptr().offset(index as isize) as *mut src_t;
                    if (*curSource).sfx == (*rmSource).sfx
                        && curSource != rmSource
                        && (*curSource).isActive as u32 != 0
                        && (*curSource).isLooping as u32 != 0
                        && (*curSource).priority as u32 == SRCPRI_AMBIENT as i32 as u32
                    {
                        if (*curSource).isPlaying as u64 != 0 {
                            (*curSfx).masterLoopSrc = index;
                            break;
                        } else if firstInactive < 0 as i32 {
                            firstInactive = index
                        }
                    }
                    index += 1
                }
            }
            if (*curSfx).loopActiveCnt == 0 {
                if firstInactive < 0 as i32 {
                    if iskilled as u64 != 0 {
                        (*curSfx).masterLoopSrc = -(1 as i32);
                        return;
                    } else {
                        curSource = rmSource
                    }
                } else {
                    curSource =
                        &mut *srcList.as_mut_ptr().offset(firstInactive as isize) as *mut src_t
                }
                if (*rmSource).isPlaying as u64 != 0 {
                    // this was the last not stopped source, save last sample position + time
                    S_AL_SaveLoopPos(curSource, (*rmSource).alSource);
                } else {
                    // second case: all loops using this sound have stopped due to listener being of of range,
                    // and now the inactive master gets deleted. Just move over the soundpos settings to the
                    // new master.
                    (*curSource).lastTimePos = (*rmSource).lastTimePos;
                    (*curSource).lastSampleTime = (*rmSource).lastSampleTime
                }
            }
        }
    } else {
        (*curSfx).masterLoopSrc = -(1 as i32)
    };
}
/*
=================
S_AL_SrcKill
=================
*/

unsafe extern "C" fn S_AL_SrcKill(mut src: srcHandle_t) {
    let mut curSource: *mut src_t = &mut *srcList.as_mut_ptr().offset(src as isize) as *mut src_t;
    // I'm not touching it. Unlock it first.
    if (*curSource).isLocked as u64 != 0 {
        return;
    }
    // Remove the entity association and loop master status
    if (*curSource).isLooping as u64 != 0 {
        (*curSource).isLooping = qfalse;
        if (*curSource).entity != -(1 as i32) {
            let mut curEnt: *mut sentity_t =
                &mut *entityList.as_mut_ptr().offset((*curSource).entity as isize)
                    as *mut sentity_t;
            (*curEnt).srcAllocated = qfalse;
            (*curEnt).srcIndex = -(1 as i32);
            (*curEnt).loopAddedThisFrame = qfalse;
            (*curEnt).startLoopingSound = qfalse
        }
        S_AL_NewLoopMaster(curSource, qtrue);
    }
    // Stop it if it's playing
    if (*curSource).isPlaying as u64 != 0 {
        crate::src::client::qal::qalSourceStop.expect("non-null function pointer")(
            (*curSource).alSource,
        );
        (*curSource).isPlaying = qfalse
    }
    // Detach any buffers
    crate::src::client::qal::qalSourcei.expect("non-null function pointer")(
        (*curSource).alSource,
        0x1009 as i32,
        0 as i32,
    );
    (*curSource).sfx = 0 as i32;
    (*curSource).lastUsedTime = 0 as i32;
    (*curSource).priority = SRCPRI_AMBIENT;
    (*curSource).entity = -(1 as i32);
    (*curSource).channel = -(1 as i32);
    if (*curSource).isActive as u64 != 0 {
        (*curSource).isActive = qfalse;
        srcActiveCnt -= 1
    }
    (*curSource).isLocked = qfalse;
    (*curSource).isTracking = qfalse;
    (*curSource).local = qfalse;
}
/*
=================
S_AL_SrcAlloc
=================
*/

unsafe extern "C" fn S_AL_SrcAlloc(
    mut priority: alSrcPriority_t,
    mut _entnum: i32,
    mut _channel: i32,
) -> srcHandle_t {
    let mut i: i32 = 0;
    let mut empty: i32 = -(1 as i32);
    let mut weakest: i32 = -(1 as i32);
    let mut weakest_time: i32 = crate::src::sys::sys_unix::Sys_Milliseconds();
    let mut weakest_pri: i32 = 999 as i32;
    let mut weakest_gain: f32 = 1000.0f64 as f32;
    let mut weakest_isplaying: qboolean = qtrue;
    let mut weakest_numloops: i32 = 0 as i32;
    let mut curSource: *mut src_t = 0 as *mut src_t;
    i = 0 as i32;
    while i < srcCount {
        curSource = &mut *srcList.as_mut_ptr().offset(i as isize) as *mut src_t;
        // The channel system is not actually adhered to by baseq3, and not
        // implemented in snd_dma.c, so while the following is strictly correct, it
        // causes incorrect behaviour versus defacto baseq3
        // If it's locked, we aren't even going to look at it
        if !((*curSource).isLocked as u64 != 0) {
            // Is it empty or not?
            if (*curSource).isActive as u64 == 0 {
                empty = i;
                break;
            } else if (*curSource).isPlaying as u64 != 0 {
                if weakest_isplaying as u32 != 0
                    && ((*curSource).priority as u32) < priority as u32
                    && (((*curSource).priority as u32) < weakest_pri as u32
                        || (*curSource).isLooping as u64 == 0
                            && ((*curSource).scaleGain < weakest_gain
                                || (*curSource).lastUsedTime < weakest_time))
                {
                    // If it has lower priority, is fainter or older, flag it as weak
                    // the last two values are only compared if it's not a looping sound, because we want to prevent two
                    // loops (loops are added EVERY frame) fighting for a slot
                    weakest_pri = (*curSource).priority as i32;
                    weakest_time = (*curSource).lastUsedTime;
                    weakest_gain = (*curSource).scaleGain;
                    weakest = i
                }
            } else {
                weakest_isplaying = qfalse;
                if weakest < 0 as i32
                    || knownSfx[(*curSource).sfx as usize].loopCnt > weakest_numloops
                    || ((*curSource).priority as u32) < weakest_pri as u32
                    || (*curSource).lastUsedTime < weakest_time
                {
                    // Sources currently not playing of course have lowest priority
                    // also try to always keep at least one loop master for every loop sound
                    weakest_pri = (*curSource).priority as i32;
                    weakest_time = (*curSource).lastUsedTime;
                    weakest_numloops = knownSfx[(*curSource).sfx as usize].loopCnt;
                    weakest = i
                }
            }
        }
        i += 1
    }
    if empty == -(1 as i32) {
        empty = weakest
    }
    if empty >= 0 as i32 {
        S_AL_SrcKill(empty);
        srcList[empty as usize].isActive = qtrue;
        srcActiveCnt += 1
    }
    return empty;
}
