static mut streamPlaying: [qboolean; 129] = [qfalse; 129];

static mut streamSources: [ALuint; 129] = [0; 129];

static mut streamBuffers: [[ALuint; 20]; 129] = [[0; 20]; 129];

static mut streamNumBuffers: [i32; 129] = [0; 129];

